const KEY = 'hundred-k-arena-v1';
const initial = {entries:[],poll:null,vote:null};
let data = load();
let filter = 'all';
function load(){try{const parsed=JSON.parse(localStorage.getItem(KEY));return parsed && Array.isArray(parsed.entries)?{...initial,...parsed}:structuredClone(initial)}catch{return structuredClone(initial)}}
function save(){localStorage.setItem(KEY,JSON.stringify(data));render()}
function el(id){return document.getElementById(id)}
function fmt(value){return Number(value).toLocaleString('zh-CN')}
function safe(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function entriesFor(player,type){return data.entries.filter(e=>e.player===player&&(!type||e.type===type))}
function renderScores(){const published=data.entries.filter(e=>e.type==='published');const day=Math.max(0,...data.entries.map(e=>Number(e.day)||0));el('hero-day').textContent=String(day).padStart(2,'0');el('status-note').textContent=day?`Day ${day} · 已录入 ${published.length} 条视频`:'Day 0 · 等待首条视频发布';for(const p of ['a','b']){const videos=entriesFor(p,'published');const best=Math.max(0,...videos.map(v=>Number(v.views)||0));const total=videos.reduce((n,v)=>n+(Number(v.views)||0),0);const followers=videos.reduce((n,v)=>n+(Number(v.followers)||0),0);const week=Math.floor(Math.max(day-1,0)/7);const rejected=entriesFor(p,'rejected').filter(v=>Math.floor(Math.max(Number(v.day)-1,0)/7)===week).length;el(`${p}-best`).textContent=videos.length?fmt(best):'—';el(`${p}-total`).textContent=videos.length?fmt(total):'—';el(`${p}-followers`).textContent=videos.length?`+${fmt(followers)}`:'—';el(`${p}-published`).textContent=videos.length;el(`${p}-rejected`).textContent=rejected;el(`${p}-progress`).style.width=`${Math.min(100,best/1000)}%`;el(`${p}-status`).textContent=best>=100000?'已达十万':videos.length?'挑战中':'待开赛'}const a=Math.max(0,...entriesFor('a','published').map(v=>Number(v.views)||0));const b=Math.max(0,...entriesFor('b','published').map(v=>Number(v.views)||0));const verdict=el('verdict').querySelector('p');if(a>=100000||b>=100000){const winner=a>=100000&&b>=100000?'双方均已破十万，请按最先达标的记录判定':a>=100000?'阿零已达到单条十万播放':'时休已达到单条十万播放';verdict.textContent=winner+'。请核对平台播放数据和达标时间。'}else if(day>=30&&published.length){verdict.textContent=`30 天已结束。阿零单条最高 ${fmt(a)}，时休单条最高 ${fmt(b)}。${a===b?'目前持平，请人工确认最终规则。':a>b?'阿零暂居领先。':'时休暂居领先。'}`}else{verdict.textContent='谁先有单条视频达到 10 万播放，谁立即获胜。30 天无人达标，则比较各自单条最高播放。'}}
const typeText={published:'视频发布',rejected:'审核打回',approved:'审核通过',reflection:'每日复盘'};
function renderEntries(){const items=data.entries.filter(e=>filter==='all'||e.player===filter).sort((a,b)=>Number(b.day)-Number(a.day)||Number(b.created)-Number(a.created));const box=el('entries');if(!items.length){box.innerHTML='<div class="empty"><div><b>赛场还空着。</b><p>Day 0 的人设选择和首条视频发布后，对决记录会从这里开始。<br>点击右上角“录入数据”可添加实际记录。</p></div></div>';return}box.innerHTML=items.map(e=>`<article class="entry"><span class="entry-day">DAY ${String(e.day).padStart(2,'0')}</span><span class="entry-player ${e.player}">${e.player==='a'?'阿零':'时休'} · ${typeText[e.type]||'记录'}</span><div><h3>${safe(e.title)}</h3><p>${safe(e.note)}</p></div><span class="entry-meta">${e.type==='published'&&e.views!==''?`${fmt(e.views)} 播放`:typeText[e.type]||''}</span></article>`).join('')}
function renderPoll(){const box=el('vote-options'),poll=data.poll;if(!poll||!Array.isArray(poll.options)||poll.options.length<2){el('vote-target').textContent='等待选题';box.innerHTML='';el('vote-note').textContent='阿零和时休还没有提交候选题。开赛后，在这里选下一期。';return}el('vote-target').textContent=`${poll.player==='a'?'阿零':'时休'} · Day ${poll.day}`;box.innerHTML=poll.options.map((o,i)=>`<button class="vote-option ${data.vote?.pollId===poll.id&&data.vote.index===i?'selected':''}" data-vote="${i}"><span>${String(i+1).padStart(2,'0')}　${safe(o)}</span><small>${data.vote?.pollId===poll.id&&data.vote.index===i?'已选择':'选择 ↗'}</small></button>`).join('');el('vote-note').textContent=data.vote?.pollId===poll.id?'已在这台设备上记录你的选择。本机演示不会汇总其他观众的票。':'请选择一个候选题。本机演示不会汇总其他观众的票。'}
function render(){renderScores();renderEntries();renderPoll()}
document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>{filter=btn.dataset.filter;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b===btn));renderEntries()}));
el('vote-options').addEventListener('click',e=>{const b=e.target.closest('[data-vote]');if(!b||!data.poll)return;data.vote={pollId:data.poll.id,index:Number(b.dataset.vote)};save()});
const dialog=el('admin-dialog');el('open-admin').addEventListener('click',()=>dialog.showModal());
function message(text){el('admin-message').textContent=text}
el('save-entry').addEventListener('click',()=>{const type=el('entry-type').value,player=el('entry-player').value,day=Number(el('entry-day').value),title=el('entry-title').value.trim(),views=el('entry-views').value,followers=el('entry-followers').value,note=el('entry-note').value.trim();if(!title||!Number.isInteger(day)||day<0||day>30){message('请填写标题和 0～30 的 Day。');return}if(type==='published'&&entriesFor(player,'published').length>=15){message('这位 AI 已录入 15 条视频，不能继续添加发布记录。');return}if(type==='rejected'){const week=Math.floor(Math.max(day-1,0)/7);if(entriesFor(player,'rejected').filter(e=>Math.floor(Math.max(Number(e.day)-1,0)/7)===week).length>=2){message('这位 AI 本周已被打回 2 次，不能继续录入打回。');return}}data.entries.push({id:crypto.randomUUID(),type,player,day,title,views:views===''?'':Math.max(0,Number(views)),followers:followers===''?'':Math.max(0,Number(followers)),note,created:Date.now()});save();el('entry-title').value='';el('entry-views').value='';el('entry-followers').value='';el('entry-note').value='';message('记录已保存到本机浏览器。')});
el('save-poll').addEventListener('click',()=>{const options=el('poll-options').value.split('\n').map(x=>x.trim()).filter(Boolean);const day=Number(el('poll-day').value);if(options.length<2||options.length>3||!Number.isInteger(day)||day<1||day>30){message('请输入 2～3 个候选题，以及 1～30 的截止 Day。');return}data.poll={id:crypto.randomUUID(),player:el('poll-player').value,day,options};data.vote=null;save();message('候选题已更新。本机演示票数已重置。')});
el('export-data').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='冲十万实验场-备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('备份已下载。')});
el('import-data').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.entries)||parsed.entries.some(x=>!['a','b'].includes(x.player)||!['published','rejected','approved','reflection'].includes(x.type)))throw Error('格式不正确');if(!confirm('导入会替换当前浏览器里的全部对决记录。继续吗？'))return;data={entries:parsed.entries,poll:parsed.poll||null,vote:parsed.vote||null};save();message('备份导入完成。')}catch{message('导入失败：文件格式不正确。')}finally{e.target.value=''}});
render();
